"""
Cache type definitions.
"""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

###############################################################################
# Cache Keys
###############################################################################

type CacheKey = str

type CachePrefix = str

###############################################################################
# Cache Values
###############################################################################

type CacheValue = Any

###############################################################################
# Time-to-Live
###############################################################################

type CacheTTL = int | float | None

###############################################################################
# Cache Mapping
###############################################################################

type CacheMapping = Mapping[
    CacheKey,
    CacheValue,
]

###############################################################################
# Public Exports
###############################################################################

__all__: tuple[str, ...] = (
    "CacheKey",
    "CacheMapping",
    "CachePrefix",
    "CacheTTL",
    "CacheValue",
)
